  (SELECT "label" FROM "molecule" WHERE "molecule_id" = 'TR018');

SELECT
  (SELECT "bond_type" FROM "bond" WHERE "molecule_id" = 'TR018' GROUP BY "bond_type" ORDER BY COUNT("bond_type") DESC LIMIT 1) AS "MajorityBondType",
  (SELECT "label" FROM "molecule" WHERE "molecule_id" = 'TR018') AS "CarcinogenicStatus";

